// DifficultyLevel は語彙帯ごとの難易度指定（prompts.DIFFICULTY_LEVELS）。
//
// Python の最上位帯は max_vocab が float("inf") なので、Go では
// math.MaxInt を使う（estimated_vocab がこれを超えることはない）。
type DifficultyLevel struct {
	MaxVocab  int
	Label     string
	VocabHint string
}

// difficultyLevels は max_vocab の昇順。
var difficultyLevels = []DifficultyLevel{
	{MaxVocab: 99, Label: "入門", VocabHint: "超基本的な挨拶・身近な語彙のみ。ターゲット単語以外は日常会話の語に置き換える（×โบราณสถาน →○วัดเก่า／×งดงาม →○สวย／×จุดหมาย →○ที่ที่จะไป／×ทราบ →○รู้／×สถานที่ →○ที่）"},
	{MaxVocab: 299, Label: "初級", VocabHint: "基本的な日常語彙のみ。ターゲット単語以外に書き言葉の名詞・文語の副詞を使わない"},
	{MaxVocab: 599, Label: "初中級", VocabHint: "日常語彙中心、やや応用的な表現も可"},
	{MaxVocab: 1499, Label: "中級", VocabHint: "日常〜応用的な語彙、自然な表現"},
	{MaxVocab: math.MaxInt, Label: "上級", VocabHint: "制限なし。慣用句・ネイティブに近い自然な表現"},
}

